-- Whether the provider of an imported event gives its end (ADR-006, decision 5). Without one, ends_at stays the end
-- of the start day in Europe/Kyiv, so sessions, cutoffs and the date filter work as before, and this column says
-- that the end is a placeholder. Organization events always have an end, hence the default. nearby_import's table
-- grants on events cover the column.
ALTER TABLE "events"
    ADD COLUMN "end_time_known" BOOLEAN NOT NULL DEFAULT true;

-- Imported events saved so far: the import wrote the last millisecond of the Kyiv day when the provider gave no end.
UPDATE "events"
SET "end_time_known" = false
WHERE "source" = 'import'
  AND ("ends_at" AT TIME ZONE 'Europe/Kyiv')::time = '23:59:59.999';
